 * Randomiza e ajusta os valores estatísticos de um jogo.
 * @param {object} stats - Objeto com min, media, max e chance.
 * @returns {object} Os valores ajustados.
 */
function atualizarValores({ min, media, max, chance }) {
    // Ajusta valores numéricos (min, media, max) em +/- 10%
    const randomMultiplier = 1 + (Math.random() * 0.2 - 0.1);

    return {
        min: min * randomMultiplier,
        media: media * randomMultiplier,
        max: max * randomMultiplier,
        // Ajusta chance em +/- 5%, limitando entre 1 e 100
        chance: Math.max(1, Math.min(100, chance + Math.floor(Math.random() * 11) - 5)) 
